1	import { cache } from "react";
2	import { cacheLife, cacheTag } from "next/cache";
3	import { fetchEventCountExternal } from "@lib/api/events-external";
4	import {
5	  buildEventsQuery,
6	  getInternalApiUrl,
7	  getVercelProtectionBypassHeaders,
8	} from "@utils/api-helpers";
9	import { eventsTag } from "@lib/cache/tags";
10	import { SITEMAP_MIN_EVENTS_FOR_EXPANSION } from "@utils/constants";
11	import type { PlaceType } from "types/common";
12	
13	async function resolvePlaceExpandability(
14	  slug: string,
15	  type: PlaceType,
16	  fetchCount: (slug: string) => Promise<number | null>,
17	): Promise<boolean> {
18	  if (type !== "town") return true;
19	  if (!slug || slug === "catalunya") return true;
20	  try {
21	    const count = await fetchCount(slug);
22	    return count === null || count >= SITEMAP_MIN_EVENTS_FOR_EXPANSION;
23	  } catch {
24	    // Fail open on unexpected errors so transient failures don't shrink
25	    // sitemap or hide internal links.
26	    return true;
27	  }
28	}
29	
30	// Metadata-only count reader: hits the internal API route with a plain,
31	// tagged `fetch()` instead of `fetchEventCountExternal` (which goes through
32	// `fetchWithHmac`, and that calls `connection()` unconditionally). Calling a
33	// dynamic API from inside a "use cache" scope defeats the whole point of
34	// getPlaceExpandabilityForMetadata below — it would stay a resume-mismatch
35	// hazard despite the "use cache" wrapper.
36	async function fetchEventCountForMetadata(slug: string): Promise<number | null> {
37	  const queryString = buildEventsQuery({ place: slug, size: 1 });
38	  const url = await getInternalApiUrl(`/api/events?${queryString}`, {
39	    preferConfiguredOrigin: true,
40	  });
41	  const response = await fetch(url, {
42	    headers: getVercelProtectionBypassHeaders(),
43	    next: { revalidate: 600, tags: [eventsTag] },
44	  });
45	  if (!response.ok) return null;
46	  const data = await response.json();
47	  return typeof data?.totalElements === "number" ? data.totalElements : null;
48	}
49	
50	/**
51	 * Determines whether a place has enough event depth to warrant filter
52	 * expansion (date/category internal links and sitemap entries).
53	 *
54	 * REGIONs and the virtual "catalunya" slug always qualify (they aggregate
55	 * events from many cities). CITYs/towns qualify only when their total event
56	 * count meets the threshold.
57	 *
58	 * On API failure or unexpected error, returns true (fail-open) so transient
59	 * issues don't silently hide internal links or shrink the sitemap.
60	 *
61	 * Single source of truth: used by /[place] pages (SSR depth + noindex meta),
62	 * PlacePageShell (explore-nav internal links), and app/sitemap-places/[...parts]
63	 * (sitemap entries). All four surfaces stay in lock-step — if sitemap drops a
64	 * URL, the page also stops emitting internal links to it. Otherwise Googlebot
65	 * keeps discovering them via crawl, treats them as near-duplicates of the
66	 * parent, and buckets them as "Crawled — currently not indexed" (Dec 2025–May
67	 * 2026 GSC drop, ~93K URLs).
68	 *
69	 * Lives in `lib/seo/` rather than `utils/` because it depends on React caching
70	 * and API I/O; `utils/` is reserved for deterministic, side-effect-free
71	 * helpers.
72	 */
73	export const getPlaceExpandability = cache(
74	  (slug: string, type: PlaceType): Promise<boolean> =>
75	    resolvePlaceExpandability(slug, type, fetchEventCountExternal),
76	);
77	
78	// Metadata-only reader: wraps the same check in `"use cache"` so
79	// generateMetadata stays prerenderable under cacheComponents. See
80	// docs/incidents/2026-06-13-cachecomponents-metadata-resume-mismatch.md.
81	export async function getPlaceExpandabilityForMetadata(
82	  slug: string,
83	  type: PlaceType,
84	): Promise<boolean> {
85	  "use cache";
86	  cacheTag(eventsTag);
87	  cacheLife("hours");
88	  return resolvePlaceExpandability(slug, type, fetchEventCountForMetadata);
89	}
