66	// docs/incidents/2026-06-13-cachecomponents-metadata-resume-mismatch.md.
67	export async function fetchCategoriesForMetadata(): Promise<
68	  CategorySummaryResponseDTO[]
69	> {
70	  "use cache";
71	  cacheTag(categoriesTag);
72	  const url = await getInternalApiUrl(`/api/categories`, {
