17	// Normalize subtitles for LLM/AI SEO extractability:
18	// - Remove HTML
19	// - Replace multiple spaces
20	// - Replace exclamations with periods
21	// - Limit to at most two sentences
22	// - Cap length to ~200 chars, cutting at last space
23	function normalizeSubTitle(input: string): string {
24	  let s = (input || "")
25	    .replace(/<[^>]*>/g, "")
26	    .replace(/\s+/g, " ")
27	    .trim();
28	  if (!s) return s;
29	  s = s.replace(/!/g, ".");
30	
31	  // Limit to two sentences (., ?, !)
32	  const ends: number[] = [];
33	  for (let i = 0; i < s.length; i++) {
34	    const ch = s[i];
35	    if (ch === "." || ch === "?" || ch === "!") ends.push(i);
36	    if (ends.length === 2) break;
37	  }
38	  if (ends.length === 2) {
39	    s = s.slice(0, ends[1] + 1);
40	  }
41	
42	  // Cap length to 200 chars
43	  const MAX_LEN = 200;
44	  if (s.length > MAX_LEN) {
45	    const cut = s.slice(0, MAX_LEN);
46	    const lastSpace = cut.lastIndexOf(" ");
47	    s = (lastSpace > 0 ? cut.slice(0, lastSpace) : cut).trim();
48	    if (!/[.!?]$/.test(s)) s += ".";
49	  }
50	
51	  return s;
52	}
