21	/**
22	 * Get the full external API URL (e.g. "https://api.esdeveniments.cat/api").
23	 *
24	 * Uses indirect env access so Turbopack does NOT inline the value at build
25	 * time. This means the runtime value (set by Coolify / Docker ENV) is always
26	 * read, and when the var is genuinely absent the JSON default kicks in.
27	 */
28	const _envKey = "NEXT_PUBLIC_API_URL";
29	export function getApiUrl(): string {
30	  return process.env[_envKey] || DEFAULT_API_URL;
31	}
32	
33	/**
34	 * Report whether NEXT_PUBLIC_API_URL is explicitly configured at runtime.
35	 * Uses the same indirect env lookup as getApiUrl() to avoid build-time
36	 * inlining. Callers use this to decide between hitting the default
37	 * production URL and taking a safe fallback path (e.g., throw for
38	 * mutations, return empty payload for read wrappers).
39	 */
40	export function isApiUrlConfigured(): boolean {
41	  return Boolean(process.env[_envKey]);
42	}
