44	// Conditionally import headers - only available in server components/route handlers
45	// Using dynamic require to avoid build-time errors when headers() is not available
46	
47	let headersFn: HeadersFn | null = null;
48	try {
49	  // Dynamic require is safe here - we catch errors if headers() is unavailable
50	  const headersModule = require("next/headers") as { headers: HeadersFn };
51	  headersFn = headersModule.headers;
52	} catch {
53	  // headers() not available (e.g., during build or in client context)
54	  headersFn = null;
55	}
