57	/**
58	 * Get API origin with multiple fallback strategies for Edge Runtime
59	 * Edge runtime has limitations with environment variables
60	 */
61	export function getApiOrigin(): string {
62	  // Strategy 1: Try environment variable (works in most cases).
63	  // Use indirect lookup so Turbopack does NOT inline at build time.
64	  const apiUrl = process.env[_envKey];
65	  if (apiUrl) {
66	    try {
67	      return new URL(apiUrl).origin;
68	    } catch {
69	      console.warn("Invalid NEXT_PUBLIC_API_URL format:", apiUrl);
70	    }
71	  }
72	
73	  // Strategy 2: Default fallback (single source of truth: config/api-defaults.json)
74	  return DEFAULT_API_ORIGIN;
75	}
